    struct Sample {let points:[CGPoint],rotation:Double,opacity:Double}
    static func cubic(_ x:Double,_ x1:Double,_ y1:Double,_ x2:Double,_ y2:Double)->Double {
        let x=min(1,max(0,x));var low=0.0,high=1.0
        for _ in 0..<36 {let t=(low+high)/2,u=1-t,p=3*u*u*t*x1+3*u*t*t*x2+t*t*t;if p<x{low=t}else{high=t}}
        let t=(low+high)/2,u=1-t;return 3*u*u*t*y1+3*u*t*t*y2+t*t*t
    }
    static func sample(_ fraction:Double,reducedMotion:Bool=false)->Sample {
        let progress=fraction.isFinite ? fraction-floor(fraction):0
        if reducedMotion {
            let first=progress<=0.5,local=first ? progress*2:(progress-0.5)*2
            let eased=cubic(local,0.42,0,0.58,1)
            return .init(points:[],rotation:0,opacity:first ? 1-0.6*eased:0.4+0.6*eased)
        }
        let index=(0..<7).first{progress<offsets[$0+1]} ?? 6
        let local=(progress-offsets[index])/(offsets[index+1]-offsets[index])
        let eased=cubic(local,0.34,1.45,0.4,1)
        var points:[CGPoint]=[]
        let factor=CGFloat(eased)
        for (a,b) in zip(polygons[index],polygons[index+1]) {
            let x=a.x+(b.x-a.x)*factor,y=a.y+(b.y-a.y)*factor
            points.append(.init(x:x,y:y))
        }
        return .init(points:points,rotation:rotations[index]+(rotations[index+1]-rotations[index])*eased,opacity:1)
    }
}
struct AWCNativeLoadingPolygon:Shape {
    let points:[CGPoint]
    func path(in rect:CGRect)->Path {
        guard let first=points.first else{return Path()};var path=Path()
        path.move(to:.init(x:rect.minX+first.x*rect.width,y:rect.minY+first.y*rect.height))
        for point in points.dropFirst(){path.addLine(to:.init(x:rect.minX+point.x*rect.width,y:rect.minY+point.y*rect.height))};path.closeSubpath();return path
    }
}
